### PricingCard.tsx
```tsx
import { useState } from 'react';
import { CheckIcon } from 'lucide-react';

export interface Plan {
  name: string;
  price: number;
  period: 'monthly' | 'yearly';
  features: string[];
}

export interface PricingCardProps {
  plan: Plan;
  onTogglePeriod: (period: 'monthly' | 'yearly') => void;
  onBuy: () => void;
}

export default function PricingCard({
  plan,
  onTogglePeriod,
  onBuy,
}: PricingCardProps) {
  const [period, setPeriod] = useState<'monthly' | 'yearly'>(
    plan.period === 'yearly' ? 'yearly' : 'monthly'
  );

  const togglePeriod = () => {
    onTogglePeriod(period === 'monthly' ? 'yearly' : 'monthly');
  };

  const formattedPrice = period === 'monthly'
    ? `$${plan.price}/month`
    : `$${plan.price * 12}/year`;

  return (
    <div className="bg-white rounded-xl shadow-md overflow-hidden transition-all duration-300 hover:shadow-lg">
      <div className="p-6">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-2xl font-semibold text-gray-800">{plan.name}</h2>
          <button
            onClick={togglePeriod}
            className="flex items-center gap-1 px-3 py-1 text-sm font-medium rounded-full border border-gray-300 bg-gray-50 hover:bg-gray-100 transition-colors"
          >
            {period === 'monthly' ? 'Monthly' : 'Yearly'}
            <span className="text-sm text-gray-500">→</span>
          </button>
        </div>

        <div className="mb-6">
          <span className="text-4xl font-bold text-gray-900">{formattedPrice}</span>
        </div>

        <ul className="space-y-3 mb-6">
          {plan.features.map((feature, index) => (
            <li key={index} className="flex items-center gap-3">
              <CheckIcon className="w-5 h-5 text-accent" />
              <span className="text-gray-700">{feature}</span>
            </li>
          ))}
        </ul>

        <button
          onClick={onBuy}
          className="w-full py-3 bg-accent text-white font-semibold rounded-lg hover:bg-blue-600 transition-colors text-center"
        >
          Buy Now
        </button>
      </div>
    </div>
  );
}
